import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 998244353;
    static final int ROOT = 3;

    static long modExp(long base, int exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static void fftTransform(long[] array, int length, int direction) {
        int n = length;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            for (; j >= bit; bit >>= 1) j -= bit;
            j += bit;
            if (i < j) {
                long temp = array[i];
                array[i] = array[j];
                array[j] = temp;
            }
        }
        for (int size = 2; size <= n; size <<= 1) {
            long wlen = modExp(ROOT, (MOD - 1) / size);
            if (direction == -1) wlen = modExp(wlen, MOD - 2);
            for (int start = 0; start < n; start += size) {
                long w = 1;
                for (int k = start; k < start + size / 2; k++) {
                    long u = array[k];
                    long v = array[k + size / 2] * w % MOD;
                    array[k] = (u + v) % MOD;
                    array[k + size / 2] = (u - v + MOD) % MOD;
                    w = w * wlen % MOD;
                }
            }
        }
        if (direction == -1) {
            long invN = modExp(n, MOD - 2);
            for (int i = 0; i < n; i++) array[i] = array[i] * invN % MOD;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), m = sc.nextInt();
        int size = 1, halfN = n / 2;
        while (size < (9 * halfN + 1)) size <<= 1;
        long[] polyA = new long[size];
        long[] polyB = new long[size];

        polyA[0] = 1;
        for (int i = 0; i < m; i++) {
            int x = sc.nextInt();
            polyB[x] = 1;
        }

        fftTransform(polyA, size, 1);
        fftTransform(polyB, size, 1);

        for (int i = 0; i < size; i++) {
            if (polyA[i] != 0 && polyB[i] != 0) {
                polyA[i] = polyA[i] * modExp(polyB[i], halfN) % MOD;
            } else {
                polyA[i] = 0;
            }
        }

        fftTransform(polyA, size, -1);

        long totalSum = 0;
        for (int i = 0; i < size; i++) {
            totalSum = (totalSum + polyA[i] * polyA[i]) % MOD;
        }
        System.out.println(totalSum);
        sc.close();
    }
}
